function peakCell(grid: number[][]): number[] {
  const m = grid.length, n = grid[0].length;
  const at = (i: number, j: number) => (i < 0 || j < 0 || i >= m || j >= n ? -1 : grid[i][j]);
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) {
      const v = grid[i][j];
      if (v > at(i - 1, j) && v > at(i + 1, j) && v > at(i, j - 1) && v > at(i, j + 1)) return [i, j];
    }
  return [-1, -1];
}

