function peakCell(grid: number[][]): number[] {
  const m = grid.length, n = grid[0].length;
  let lo = 0, hi = n - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    let r = 0;
    for (let i = 1; i < m; i++) if (grid[i][mid] > grid[r][mid]) r = i;
    const left = mid > 0 ? grid[r][mid - 1] : -1;
    const right = mid < n - 1 ? grid[r][mid + 1] : -1;
    const v = grid[r][mid];
    if (v > left && v > right) return [r, mid];
    if (right > v) lo = mid + 1;
    else hi = mid - 1;
  }
  return [-1, -1];
}

